// AvgustovStory 1.3.0 (25.11.2026, user: "еженедельные заказы Ратибора"): weekly rotation of «Заказы Ратибора».
// Every Monday 00:00 Moscow time four orders (one per tier) are picked from the pool in avgustov_ratibor_orders.js
// (generated by quest_generator/gen/ratibor.js). Each order quest is hidden until its invisible gate quest is done.
// On a new week, once per FTB team (team id + week number in server.persistentData):
//   reset every order and gate quest, then complete the gates of this week's orders (/ftbquests change_progress).
// The team is updated when one of its players logs in or, for players online at midnight, by the minute check below.
var RTB_SQF = Java.loadClass('dev.ftb.mods.ftbquests.quest.ServerQuestFile');
var RTB_DAY = 86400000;

// week number, weeks starting Monday 00:00 UTC+3 (1970-01-01 was a Thursday)
function rtbWeek() { return Math.floor((Date.now() + 3 * 3600000 - 4 * RTB_DAY) / (7 * RTB_DAY)); }
function rtbRnd(a, b) { var x = Math.sin(a * 12.9898 + b * 78.233 + 1.618) * 43758.5453; return x - Math.floor(x); }
// one order per tier; never the same order two weeks running
function rtbPick(w) {
  var out = [];
  for (var t = 0; t < RATIBOR_TIERS.length; t++) {
    var pool = RATIBOR_ORDERS.filter(function (o) { return o.tier === t; });
    if (!pool.length) continue;
    var i = Math.floor(rtbRnd(w, t) * pool.length), prev = Math.floor(rtbRnd(w - 1, t) * pool.length);
    if (pool.length > 1 && i === prev) i = (i + 1) % pool.length;
    out.push(pool[i]);
  }
  return out;
}
function rtbTeam(p) {
  try { return String(RTB_SQF.INSTANCE.getOrCreateTeamData(p).getTeamId()); } catch (err) { return 'p_' + String(p.uuid); }
}
// returns true when the player's team got this week's board now
function rtbApply(p, w) {
  var s = p.server, pd = s.persistentData, key = 'rtb_' + rtbTeam(p);
  if (pd.contains(key) && pd.getInt(key) === w) return false;
  var n = p.username;
  RATIBOR_ORDERS.forEach(function (o) {
    s.runCommandSilent('ftbquests change_progress ' + n + ' reset ' + o.id);
    s.runCommandSilent('ftbquests change_progress ' + n + ' reset ' + o.gate);
  });
  rtbPick(w).forEach(function (o) { s.runCommandSilent('ftbquests change_progress ' + n + ' complete ' + o.gate); });
  pd.putInt(key, w);
  console.info('[ratibor] week ' + w + ' board for ' + n + ': ' + rtbPick(w).map(function (o) { return o.key; }).join(', '));
  return true;
}
function rtbTell(s, who, w) {
  var list = rtbPick(w).map(function (o) { return RATIBOR_TIERS[o.tier] + ' — ' + o.ru; }).join(' · ');
  var msg = JSON.stringify([{ text: '✎ ', color: 'dark_gray' }, { text: 'Ратибор вывесил заказы недели: ', color: 'gold' },
    { text: list, color: 'yellow' }, { text: '. Книга квестов → «Заказы Ратибора».', color: 'gray' }]);
  s.runCommandSilent('tellraw ' + who + ' ' + msg);
}

PlayerEvents.loggedIn(function (e) {
  var p = e.player, s = p.server;
  // after FTB Quests has synced the player's team data
  s.scheduleInTicks(60, function () {
    try { var w = rtbWeek(); if (rtbApply(p, w)) rtbTell(s, p.username, w); } catch (err) { console.warn('[ratibor] login: ' + err); }
  });
});

// Monday midnight while people are online: once a minute check the week number
ServerEvents.tick(function (e) {
  var s = e.server;
  if (s.tickCount % 1200 !== 0) return;
  try {
    var w = rtbWeek(), pd = s.persistentData;
    if (pd.contains('rtb_week') && pd.getInt('rtb_week') === w) return;
    pd.putInt('rtb_week', w);
    var any = false;
    s.players.forEach(function (p) { if (rtbApply(p, w)) any = true; });
    if (any) rtbTell(s, '@a', w);
  } catch (err) { console.warn('[ratibor] tick: ' + err); }
});
